<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();$keys=['seo_title'=>'Default SEO title','seo_description'=>'Default SEO description','seo_keywords'=>'Default SEO keywords'];if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();foreach($keys as $key=>$label){$value=trim((string)($_POST[$key]??''));$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute([$key,$value]);}$_SESSION['flash']='SEO settings saved.';redirect('seo.php');}$values=[];foreach($keys as $key=>$label){$s=$pdo->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$s->execute([$key]);$values[$key]=(string)($s->fetchColumn()?:'');}admin_page_start('SEO setup');?><div class="panel"><p class="text-secondary">Set default metadata for the storefront. Product pages can later have individual title and description fields.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label">Default title</label><input class="form-control mb-3" name="seo_title" maxlength="160" value="<?=e($values['seo_title'])?>"><label class="form-label">Default meta description</label><textarea class="form-control mb-3" name="seo_description" maxlength="320" rows="3"><?=e($values['seo_description'])?></textarea><label class="form-label">Keywords (comma-separated)</label><input class="form-control mb-3" name="seo_keywords" value="<?=e($values['seo_keywords'])?>"><button class="btn btn-primary">Save SEO settings</button></form><hr><h2 class="h6">Technical SEO files</h2><p class="mb-1"><a href="../sitemap.php" target="_blank">Open XML sitemap</a></p><p class="mb-0"><a href="../robots.txt" target="_blank">Open robots.txt</a></p><small class="text-secondary">Update the canonical domain and sitemap URL before production hosting.</small></div><?php admin_page_end();?>